:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --snake: #4ade80;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: 480px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.score {
  font-size: 1.125rem;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: 700;
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 8px;
  background: var(--grid);
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(22, 33, 62, 0.92);
  border-radius: 8px;
  padding: 24px;
  text-align: center;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  max-width: 320px;
}

.overlay h2 {
  font-size: 1.375rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.05s;
}

.btn:hover {
  background: var(--accent);
  color: var(--card);
}

.btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: var(--card);
}

.btn.primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score {
    font-size: 1rem;
  }
  .btn {
    padding: 10px 12px;
    font-size: 0.9375rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  let snake, dir, nextDir, food, score, state, timer;

  function init() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    state = 'paused';
    placeFood();
    updateScore();
    showOverlay('How to Play', 'Use the arrow keys to move the snake. Eat the food to grow and score points. Press <strong>Start Game</strong> or <strong>Space</strong> to begin.', 'Start Game');
    pauseBtn.textContent = 'Pause';
    clearInterval(timer);
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function updateScore() {
    scoreEl.textContent = score;
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function startGame() {
    if (state === 'over') {
      init();
    }
    state = 'running';
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    clearInterval(timer);
    timer = setInterval(tick, TICK_MS);
  }

  function pauseGame() {
    if (state !== 'running') return;
    state = 'paused';
    clearInterval(timer);
    pauseBtn.textContent = 'Resume';
    showOverlay('Paused', 'Press <strong>Resume</strong> or <strong>Space</strong> to continue.', 'Resume');
  }

  function resumeGame() {
    if (state !== 'paused') return;
    state = 'running';
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    clearInterval(timer);
    timer = setInterval(tick, TICK_MS);
  }

  function togglePause() {
    if (state === 'running') pauseGame();
    else if (state === 'paused') resumeGame();
  }

  function gameOver() {
    state = 'over';
    clearInterval(timer);
    pauseBtn.textContent = 'Pause';
    showOverlay('Game Over', 'Your score: <strong>' + score + '</strong><br>Press <strong>Restart</strong> to play again.', 'Play Again');
  }

  function tick() {
    if (state !== 'running') return;
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      gameOver();
      draw();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      draw();
      return;
    }

    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score++;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    ctx.fillStyle = '#4ade80';
    snake.forEach((s, i) => {
      ctx.fillStyle = i === 0 ? '#86efac' : '#4ade80';
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function setDirection(x, y) {
    if (state !== 'running') return;
    if (dir.x === -x && dir.y === -y) return;
    nextDir = { x, y };
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'w' || key === 'W') { e.preventDefault(); setDirection(0, -1); }
    else if (key === 'ArrowDown' || key === 's' || key === 'S') { e.preventDefault(); setDirection(0, 1); }
    else if (key === 'ArrowLeft' || key === 'a' || key === 'A') { e.preventDefault(); setDirection(-1, 0); }
    else if (key === 'ArrowRight' || key === 'd' || key === 'D') { e.preventDefault(); setDirection(1, 0); }
    else if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (state === 'running') pauseGame();
      else if (state === 'paused') resumeGame();
      else if (state === 'over') startGame();
    }
  });

  overlayBtn.addEventListener('click', () => {
    if (state === 'over') startGame();
    else if (state === 'paused') resumeGame();
    else startGame();
  });

  pauseBtn.addEventListener('click', togglePause);

  restartBtn.addEventListener('click', () => {
    clearInterval(timer);
    init();
  });

  init();
})();
